三、简单的Vue实例通过express模块渲染成html并在页面显示

```js
const Vue = require('vue');
const server = require('express')();

const template = require('fs').readFileSync('./index.template.html', 'utf-8');

const renderer = require('vue-server-renderer').createRenderer({
  template,
});

const context = {
  title: 'vue ssr',
  meta: `
        <meta charset="UTF-8">
        <meta name="keyword" content="vue,ssr">
        <meta name="description" content="vue srr demo">
    `,
};

server.get('*', (req, res) => {
  const app = new Vue({
    data: {
      url: req.url,
    },
    template: `<div>访问的 URL 是： {{ url }}</div>`,
  });

  renderer.renderToString(app, context, (err, html) => {
    if (err) {
      res.status(500).end('Internal Server Error');
      return;
    }
    res.end(html);
  });
});

server.listen(8080, () => {
  console.log('服务启动成功');
});
//浏览器地址栏输入http://localhost:8080/PageRenderingCase
```

四、简单的Vue实例结合router路由渲染页面，切换路由也是服务端处理返回html文件

```js
const server = require('express')();
//读取数据和需要填充到<!--vue-ssr-outlet-->占位符的内容
const createApp = require('./app.js');
const template = require('fs').readFileSync('./index.template.html', 'utf-8');

const renderer = require('vue-server-renderer').createRenderer({
  template,
});

const context = {
  title: 'vue ssr',
  meta: `
        <meta charset="UTF-8">
        <meta name="keyword" content="vue,ssr">
        <meta name="description" content="vue srr demo">
    `,
};

const getData = function() {
  return new Promise((reslove, reject) => {
    let str = 'this is a async data!';
    reslove(str);
  });
};

server.get('*', async (req, res) => {
  let appServer;
  try {
    const ctx = {
      url: req.url,
    };

    // 调用接口获取数据
    // 数据传递
    ctx.propsData = 'this is a data from props!';
    ctx.asyncData = await getData();

    appServer = await new Promise((reslove, reject) => {
      console.log(req.url);
      let { app, router } = createApp(ctx);
      router.push(req.url);

      //  router回调函数
      //  当所有异步请求完成之后就会触发
      //服务端匹配路由，匹配到则返回给客户端
      router.onReady(() => {
        let matchedComponents = router.getMatchedComponents();
        console.log(matchedComponents);
        if (!matchedComponents.length) {
          return reject({
            code: 404,
          });
        }
        reslove(app);
      }, reject);
    });
  } catch (error) {
    console.log(error);
  }
  renderer.renderToString(appServer, context, (err, html) => {
    if (err) {
      res.status(500).end('Internal Server Error');
      return;
    }
    res.end(html);
  });
});

server.listen(8080, () => {
  console.log('服务启动成功 http://127.0.0.1:8080');
});

```

