import { h, reactive } from "vue";
export default {
  setup(props, { slots, attrs, emit }) {
    const state = reactive({
      count: 0,
    });

    function increment() {
      state.count++;
    }
    // 返回render函数
    return () =>
      h(
        "div",
        {
          onClick: increment,
        },
        [slots.default(), slots.content({ data: "jack" }), state.count, h("input", { value: "123456" }, ["我是span"])]
      );
  },
};
其中，h为函数，不再是参数，格式：h('标签名',{属性或事件},[子元素或h函数])

