  // 就新建一个空的发布者对象集
    depMap = new Map()
    // 然后再把这个发布者对象集存进 WeakMap 里
    targetToHashMap.set(target, depMap)
  }
// 再获取到这个发布者对象集里的某一个键所对应的发布者对象
  let dep = depMap.get(key)
  // 如果没获取到的话
  if (!dep) {
   // 就新建一个发布者对象并初始化赋值
    dep = new Dep(target[key])
    // 然后将这个发布者对象放入到发布者对象集里
    depMap.set(key, dep)
  }
