        // 获取余数，入栈(算法：第一次的余数对应二进制的第一位)
        stack.push(decNumber%2);
        // 向下取整，继续循环
        decNumber = Math.floor(decNumber/2);
    }
    let res='';
    while(!stack.isEmpty()){
        res+=stack.pop()
    }
    return res
}
