## 优先级队列

**1.什么是优先级队列**

定义：它会自动根据元素的优先级将其插入到合适的位置。当你从 PriorityQueue 中删除一个元素时，它会自动将优先级最高的元素出队。

**2.优先级队列的应用**

- **数据压缩**：赫夫曼编码算法；
- **最短路径算法**：Dijkstra 算法；
- **最小生成树算法**：Prim 算法；
- **任务调度器**：根据优先级执行系统任务；
- **事件驱动仿真**：顾客排队算法；
- **排序问题**：查找第 k 个最小元素。

**3.实现优先级队列**

三种方案实现优先级队列：

- **数组（顺序存储）实现优先队列**：入队操作直接插入到数组队尾，时间复杂度为 *O*(1)。出队操作需要遍历整个数组，找到优先级最高的元素，返回并删除该元素，时间复杂度为 O*(*n)。
- **链表（链式存储）实现优先队列**：链表中的元素按照优先级排序，入队操作需要为待插入元素创建节点，并在链表中找到合适的插入位置，时间复杂度为 O*(*n)。出队操作直接返回链表队头元素，并删除队头元素，时间复杂度为 O(1)。
- **二叉堆结构实现优先队列**：构建一个二叉堆结构，二叉堆按照优先级进行排序。入队操作就是将元素插入到二叉堆中合适位置，时间复杂度为 (log⁡2)*O*(log2*n*)。出队操作则返回二叉堆中优先级最大节点并删除，时间复杂度也是 O*(log*n*)。

**3.1数组实现优先级队列**

```
// MinPriorityQueue Implementation
class PriorityQueue {
  constructor() {
    this.values = [];
  }

  enqueue(node, priority) {
    var flag = false;
    for (let i = 0; i < this.values.length; i++) {
      if (this.values[i].priority > priority) {
        this.values.splice(i, 0, { node, priority });
        flag = true;
        break;
      }
    }
    if (!flag) {
      this.values.push({ node, priority });
    }
  }

  dequeue() {
    return this.values.shift();
  }

  size() {
    return this.values.length;
  }
}

// Example Usage
var a = new PriorityQueue();
a.enqueue(10, 1);
a.enqueue(1, 0);
a.enqueue(8, 2);
```

## 链表

**1.链表特点**

- 每个元素（通常称为节点）包含两个部分：存储的数据和指向下一个节点的链接
- 不必连续空间

与数组的比较：

- 内存不必连续，充分利用内存，内存动态管理
- 必须不必确定大小，大小可无限延伸
- 插入和删除数据，可达到O(1),效率高

**2.实现链表常见操作**

![image](/img/2024-04-24_07-07-15.png)

```html
<html>
<script >
function LinkList(){
  // 内部类
  function Node(data){
    this.data =data;
    this.next = null
  }
  // 属性
  this.head = null;
  this.length = 0;
  // 添加节点
  LinkList.prototype.append=function(data){
    let node = new Node(data);
    if(this.length === 0){
      this.head = node;
    }else{
      // 遍历，找到链表的最后一个节点
      let curNode = this.head;
      while(curNode.next){
        curNode = curNode.next
      }
      curNode.next = node;
    }
    this.length+=1;
  }
    // 打印
   LinkList.prototype.toString=function(data){
      let curNode = this.head;
      let str='';
      while(curNode){
        str += ','+curNode.data;
        curNode = curNode.next;
      }
      return str.slice(1);// 把第一个逗号去掉
    }
    // 指定位置插入元素
    LinkList.prototype.insert=function(position,data){
      if(position<0||position>this.length){
        return false;
      }
      let node = new Node(data);
      if(position === 0){
        // 插入的是第一个元素：换头，先换后再换前
        node.next = this.head;
        this.head = node;
      }else{
        // 中间插入
        let index =0;
        let curNode = this.head;
        let preNode = null;
        while(index++<position){
          preNode = curNode;
          curNode = curNode.next;
        }
        node.next = curNode;
        preNode.next = node;

      }
      this.length+=1;
      return true;
    }    
    // 获取第i个元素
    LinkList.prototype.get=function(position){
        // 越界判断
        if(position<0||position>=this.length) return null;
        let index =0;
        let curNode = this.head;
        while(index++<position){
            curNode=curNode.next;
        }
        return curNode.data;
    }
    // 获取元素位置
    LinkList.prototype.indexOf=function(data){
        let index =0;
        let curNode = this.head;
        // 开始查找
        while(curNode){
            // 找到即返回索引值
            if(curNode.data===data){
                return index;
            }
            curNode=curNode.next;
            index++;
        }
        // 找到了最后
        return -1;
    }
    // 更新元素
    LinkList.prototype.update=function(position,data){
         // 越界判断
         if(position<0||position>=this.length) return false;
        let index =0;
        let curNode = this.head;
        while(index++<position){
            curNode=curNode.next;
        }
        curNode.data = data;
        return true
    }
        // 从指定位置删除元素，类似插入元素
    LinkList.prototype.removeAt=function(position){
         // 越界判断
         if(position<0||position>=this.length) return false;
          if(position === 0){
          // 删除的是第一个元素：换头，先换后再换前
            this.head = this.head.next
          }else{
            // 中间删除
            let index =0;
            let curNode = this.head;
            let preNode = null;
            while(index++<position){
              // 循环查找
              preNode = curNode;
              curNode = curNode.next;
            }
            // 前一个节点的next,指向当前节点的next
            preNode.next = curNode.next;
            }
            this.length--;
          }

           // 删除元素
     LinkList.prototype.removeAt=function(data){
          const index = this.indexOf(data);
          return this.removeAt(index)
        }
          // 是否为空
     LinkList.prototype.isEmpty=function(){
          return this.length===0;
        }
            // 链表大小
     LinkList.prototype.size=function(){
          return this.length;
        }

}
let linkList = new LinkList();
linkList.append('abc');
linkList.append('edf');
// linkList.insert(0,'123')
// linkList.removeAt(0)
alert(linkList.size())
 </script>
</html>
```

