**利用比较器，自己实现动态小根堆**

```
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
public class HeapGreater<T> {
    // 利用比较器，自己实现动态的小根堆.即增删改后，始终都是小根堆。因为系统不提供动态的小根堆，只是一个静态的小根堆.关键就是节点索引记录表，知道了i,可以上窜或下窜。
    // 加入小根堆的节点
    private ArrayList<T> heap;
    // 节点索引记录表：加入过小根堆的节点对应的索引值
    private HashMap<T, Integer> indexMap;
    private int heapSize;
    // 比较器规则
    private Comparator<? super T> comp;

    public HeapGreater(Comparator<? super T> c) {
        heap = new ArrayList<>();
        indexMap = new HashMap<>();
        heapSize = 0;
        comp = c;
    }

    public boolean isEmpty() {
        return heapSize == 0;
    }

    public int size() {
        return heapSize;
    }

    public boolean contains(T obj) {
        // 判断是否加入过小根堆
        return indexMap.containsKey(obj);
    }

    // 去除小根堆的顶部
    public T peek() {
        return heap.get(0);
    }

    // 添加节点到小根堆
    public void push(T obj) {
        // 直接先添加
        heap.add(obj);
        // 节点表添加节点索引
        indexMap.put(obj, heapSize);
        // 上窜，并且按照cop比较器规则上窜
        heapInsert(heapSize++);
    }

    // 弹出小根堆顶部节点
    public T pop() {
        // 先取出要返回的节点，然后小根堆化
        T ans = heap.get(0);
        // 交换到最后
        swap(0, heapSize - 1);
        // 两个map同步删除
        indexMap.remove(ans);
        heap.remove(--heapSize);
        // 把顶部节点下窜，并且按照cop比较器规则下窜
        heapify(0);
        return ans;
    }

    // 删除一个小根堆节点
    public void remove(T obj) {
        T replace = heap.get(heapSize - 1);
        int index = indexMap.get(obj);
        indexMap.remove(obj);
        heap.remove(--heapSize);
        if (obj != replace) {
            heap.set(index, replace);
            indexMap.put(replace, index);
            resign(replace);
        }
    }

    // 更新了节点值，重置小根堆，使其小根堆化
    public void resign(T obj) {
        // 因为不确定节点是上窜还是下窜，关键就是这个索引值即记录表
        // 要么上窜
        heapInsert(indexMap.get(obj));
        // 要么下窜
        heapify(indexMap.get(obj));
    }

    // 请返回堆上的所有元素
    public List<T> getAllElements() {
        List<T> ans = new ArrayList<>();
        for (T c : heap) {
            ans.add(c);
        }
        return ans;
    }

    // 上窜
    private void heapInsert(int index) {
        // 按照比较器规则上窜，因为是负数，所以整体是升序，对应小根堆
        while (comp.compare(heap.get(index), heap.get((index - 1) / 2)) < 0) {
            swap(index, (index - 1) / 2);
            index = (index - 1) / 2;
        }
    }

    // 下窜
    private void heapify(int index) {
        int left = index * 2 + 1;
        while (left < heapSize) {
            // 按照比较器规则下窜，因为是负数，所以整体是升序，对应小根堆
            int best = left + 1 < heapSize && comp.compare(heap.get(left + 1), heap.get(left)) < 0 ? (left + 1) : left;
            best = comp.compare(heap.get(best), heap.get(index)) < 0 ? best : index;
            if (best == index) {
                break;
            }
            swap(best, index);
            index = best;
            left = index * 2 + 1;
        }
    }

    // 交换
    private void swap(int i, int j) {
        T o1 = heap.get(i);
        T o2 = heap.get(j);
        // heap有变动，indexMap也变动，强同步
        heap.set(i, o2);
        heap.set(j, o1);
        indexMap.put(o2, i);
        indexMap.put(o1, j);
    }
}
```

