 public static int[] getHelp(int[]  arr){
     // 利用前缀和数组辅助，差值就是范围和
     int N = arr.length;
     int [] help=new int[N];
     help[0]=arr[0];
     for(int i =1;i<N;i++){
         help[i]=help[i-1]+arr[i];
     }
     return help;
 }

 public static int rangeNum(int[] arr,int L,int R,int[] help){
     //求数组任意范围的和,如求arr的3-7范围和等于help[7]-help[2]
     // 注意边界0
     return L==0?help[R]:help[R]-help[L-1];
 }
