## 单链表反转

```
import java.util.*;
import java.lang.*;
import java.io.*;
class Codechef
{
 public static void main (String[] args) throws java.lang.Exception
 {
     // 单链表反转，注意一定要有返回值的头结点，否则容易断链
     Node node0 = new Node(0);
     node0.next = new Node(1);
     node0.next.next = new Node(2);
     node0.next.next.next = new Node(3);
     print(node0);
     System.out.println();
     node0 = reverseLinkedList(node0);
     print(node0);
 }

 public static Node reverseLinkedList(Node head){
     // 单链表反转。
     //注意一定要有返回值，让头结点指针指向第一个节点。否则头结点只能指向最后一个节点，导致其他节点丢失
     Node pre = null;
     Node next = null;
     while(head != null){
      // 先将当前节点的下个节点临时保存下
       next = head.next;
      // 把当前节点的下一个节点往前指
       head.next =  pre;
       // 把前一个节点变成当前，方便下一次继续往前指
       pre = head;
       // 上面就已经完成了反转，但还需要继续遍历下去，所以用到了第一步临时的next
       head = next;
     }
     // 当node为空，停止，并返回反转后的第一个节点pre
     return pre;
 }
 public static class Node{
  // 单链表结构
     public int value;
     public Node next;
     public Node(int val){
         value = val;
     }
 }

 public static void print(Node node){
     while(node !=null){
         System.out.print(node.value+"->");
         node = node.next;
     }
 }
}
