    ans = head.value;
    // 头指针下移一个
    head = head.next;
    size--;
   }
   if (head == null) {
    tail = null;
   }
   return ans;
  }

  // C/C++的同学需要做节点析构的工作
  public V peek() {
      // 查询队列的头结点
