public static class MyStack<V> {
     // 基于链表结构的栈，先进后出。
     // 只需要用到一个头指针
  private Node<V> head;
  private int size;

  public MyStack() {
   head = null;
   size = 0;
  }

  public boolean isEmpty() {
   return size == 0;
  }

  public int size() {
   return size;
  }

  public void push(V value) {
      // 栈添加数据
   Node<V> cur = new Node<>(value);
   if (head == null) {
    head = cur;
   } else {
    // 当前节点的下一个指向老头节点
    cur.next = head;
    // 新头指向当前节点
    head = cur;
   }
   size++;
  }

  public V pop() {
      // 栈弹出数据
   V ans = null;
   if (head != null) {
    ans = head.value;
    head = head.next;
    size--;
   }
   return ans;
  }

  public V peek() {
      // 查看栈顶数据
   return head != null ? head.value : null;
  }
 }
