      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      head.next = new Node(1);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
