### 链表的复制

题目：一种特殊的单链表结构，其中有个Node rand随机属性。rand可能指向任意节点，也可能指向null.请设计一个函数完成这个链表的复制，返回复制的链表的头结点。

- 解法1：把所有节点放入hashmap,从头结点开始遍历，依次copy出新链表
- 解法2：在每个节点后面插入前一个节点的copy节点，然后设置radom，再分离新老节点

```
import java.util.HashMap;
// 测试链接 : https://leetcode.com/problems/copy-list-with-random-pointer/
public class Code04_CopyListWithRandom {
 public static class Node {
  int val;
  Node next;
  Node random;

  public Node(int val) {
   this.val = val;
   this.next = null;
   this.random = null;
  }
 }

 // 解法1：把所有节点放入hashmap,从头结点开始遍历，依次copy出新链表
 public static Node copyRandomList1(Node head) {
  // key 老节点
  // value 新节点
  HashMap<Node, Node> map = new HashMap<Node, Node>();
  Node cur = head;
  // 所有节点放入hashmap
  while (cur != null) {
   map.put(cur, new Node(cur.val));
   cur = cur.next;
  }
  cur = head;
  // 从头结点开始遍历，依次copy
  while (cur != null) {
   // cur 老节点
   // map.get(cur) 新节点
   // 新.next ->  cur.next克隆节点找到
   map.get(cur).next = map.get(cur.next);
   map.get(cur).random = map.get(cur.random);
   cur = cur.next;
  }
  return map.get(head);
 }

 // 解法2：在每个节点后面插入前一个节点的copy节点，然后设置radom，再分离新老节点
 public static Node copyRandomList2(Node head) {
  if (head == null) {
   return null;
  }
  Node cur = head;
  Node next = null;
  // 1 -> 2 -> 3 -> null
  // 1 -> 1' -> 2 -> 2' -> 3 -> 3'
  // 每个节点后面插入前一个节点的copy节点
  while (cur != null) {
   next = cur.next;
   cur.next = new Node(cur.val);
   cur.next.next = next;
   cur = next;
  }
  cur = head;
  Node copy = null;
  // 1 1' 2 2' 3 3'， 其中1‘是1的复制节点
  // 依次设置 1' 2' 3' 的random指针
  while (cur != null) {
   next = cur.next.next;
   copy = cur.next;
   // 注意cur.random的节点 一定是对应cur.random.next。因为下一个节点是当前节点的复制。
   copy.random = cur.random != null ? cur.random.next : null;
   cur = next;
  }
  Node res = head.next;
  cur = head;
  // 老 新 混在一起，next方向上，random正确
  // next方向上，把新老链表分离，一定动手实际画图，想是想不清楚的
  while (cur != null) {
   next = cur.next.next;
   copy = cur.next;
   cur.next = next;
   copy.next = next != null ? next.next : null;
   cur = next;
  }
  return res;
 }
}
```

### 两链表是否相交

题目：给定两个可能有环也可能无环的单链表，头节点head1和head2。请实 现一个函数，如果两个链表相交，请返回相交的 第一个节点。如果不相交，返 回null。要求时间复杂度O(N),空间复杂度O(1)

思路：这是一个超大题目。涉及知识点：

- 必考知识点：找到链表第一个入环节点，如果无环，返回null
- 必考知识点：如果两个链表都无环，返回第一个相交节点，如果不想交，返回null
- 必考知识点：两个有环链表，返回第一个相交节点，如果不想交返回null

解法：

- 解法：先求链表的入环节点，然后按照无环和有环分情况讨论

```java
public class Code01_FindFirstIntersectNode {
   public static class Node {
      public int value;
      public Node next;
      public Node(int data) {
         this.value = data;
      }
   }

   public static Node getIntersectNode(Node head1, Node head2) {
      // 解法：先求链表的入环节点，然后按照无环和有环分情况讨论
      if (head1 == null || head2 == null) {
         return null;
      }
      // 找到链表第一个入环节点，如果无环，返回null
      Node loop1 = getLoopNode(head1);
      Node loop2 = getLoopNode(head2);
      // 如果两个链表都是无环链表
      if (loop1 == null && loop2 == null) {
         return noLoop(head1, head2);
      }
      // 如果两个链表都是有环链表
      if (loop1 != null && loop2 != null) {
         return bothLoop(head1, loop1, head2, loop2);
      }
      // 一链表有环，一链表无环，一定不会相交。画画图就知道了
      return null;
   }

   // 必考知识点：找到链表第一个入环节点，如果无环，返回null
   public static Node getLoopNode(Node head) {
      /*
      * 解法1：用额外空间，遍历链表，每到一个节点就判断是否在Set里，如果突然发现在了。说明是第一个入环节点。
      * 解法2：快慢指针，慢指针一定不会走够两圈以上，在环内相遇时，将快指针放到开头，慢指针原地不动。然后两个开始一次走一步，最后会在入环节点相遇。本文采用解法2.
      * */
      if (head == null || head.next == null || head.next.next == null) {
         return null;
      }
      // n1 慢指针  n2 快指针，让n1,n2都先走一次，方便下面的while判断
      Node slow = head.next; // n1 -> slow
      Node fast = head.next.next; // n2 -> fast
      while (slow != fast) {
         if (fast.next == null || fast.next.next == null) {
            return null;
         }
         fast = fast.next.next;
         slow = slow.next;
      }
      // 到这里，说明slow fast  相遇了
      // 抖机灵做法：快指针回到头结点，然后快慢指针再次相遇，就是入环节点
      fast = head; // n2 -> walk again from head
      while (slow != fast) {
         slow = slow.next;
         fast = fast.next;
      }
      return slow;
   }

   // 必考知识点：如果两个链表都无环，返回第一个相交节点，如果不想交，返回null
   public static Node noLoop(Node head1, Node head2) {
      /*
      * 先统计head1到end1并且记住长度假设是100，然后统计head2和end2并且记住长度假设是80。如果end1！=end2则没有相交部分。
      * 如果一样，则head1先走20步，然后一起走直到找到相同内存的节点，即相交节点。可以通过n记录链表一和二的长度之差，节约一个变量。
      * */
      if (head1 == null || head2 == null) {
         return null;
      }
      Node cur1 = head1;
      Node cur2 = head2;
      int n = 0;
      while (cur1.next != null) {
         n++;
         cur1 = cur1.next;
      }
      while (cur2.next != null) {
         n--;
         cur2 = cur2.next;
      }
      // 因为是无环链表，如果最后的节点都不相同，结果一定是不相交，后续不用执行
      if (cur1 != cur2) {
         return null;
      }
      // n 表示链表1长度减去链表2长度的值
      cur1 = n > 0 ? head1 : head2; // 谁长，谁的头变成cur1
      cur2 = cur1 == head1 ? head2 : head1; // 谁短，谁的头变成cur2
      n = Math.abs(n);
      // 长链表减去多余的部分，然后一起往下走
      while (n != 0) {
         n--;
         cur1 = cur1.next;
      }
      // 如果相遇，则是相交点
      while (cur1 != cur2) {
         cur1 = cur1.next;
         cur2 = cur2.next;
      }
      return cur1;
   }

   // 必考知识点：两个有环链表，返回第一个相交节点，如果不想交返回null
   public static Node bothLoop(Node head1, Node loop1, Node head2, Node loop2) {
      /*
      * 情况1：如果有入环节点相同
      * 情况2:如果有入环点不同，可能有两个入环点
      * 情况3：如果有入环点不同，可能不相交
      * */
      Node cur1 = null;
      Node cur2 = null;
      // 情况1：和前面的无环链表判断类似，只不过节点找到入环节点就可以，也没有入环节点的判断
      if (loop1 == loop2) {
         cur1 = head1;
         cur2 = head2;
         int n = 0;
         while (cur1 != loop1) {
            n++;
            cur1 = cur1.next;
         }
         while (cur2 != loop2) {
            n--;
            cur2 = cur2.next;
         }
         cur1 = n > 0 ? head1 : head2;
         cur2 = cur1 == head1 ? head2 : head1;
         n = Math.abs(n);
         while (n != 0) {
            n--;
            cur1 = cur1.next;
         }
         while (cur1 != cur2) {
            cur1 = cur1.next;
            cur2 = cur2.next;
         }
         return cur1;
      } else {
         // 情况2
         cur1 = loop1.next;
         // 链表1从自己的入环点开始遍历一圈，找下是否有节点和链表2的入环点相同，相同即返回节点
         while (cur1 != loop1) {
            if (cur1 == loop2) {
               return loop1;// 或返回loop2都行，因为有2个入环点，随便一个都可以
            }
            cur1 = cur1.next;
         }
         //情况3
         return null;
      }
   }

   public static void main(String[] args) {
      // 1->2->3->4->5->6->7->null
      Node head1 = new Node(1);
      head1.next = new Node(2);
      head1.next.next = new Node(3);
      head1.next.next.next = new Node(4);
      head1.next.next.next.next = new Node(5);
      head1.next.next.next.next.next = new Node(6);
      head1.next.next.next.next.next.next = new Node(7);

      // 0->9->8->6->7->null
      Node head2 = new Node(0);
      head2.next = new Node(9);
      head2.next.next = new Node(8);
      head2.next.next.next = head1.next.next.next.next.next; // 8->6
      System.out.println(getIntersectNode(head1, head2).value);

      // 1->2->3->4->5->6->7->4...
      head1 = new Node(1);
      head1.next = new Node(2);
      head1.next.next = new Node(3);
      head1.next.next.next = new Node(4);
      head1.next.next.next.next = new Node(5);
      head1.next.next.next.next.next = new Node(6);
      head1.next.next.next.next.next.next = new Node(7);
      head1.next.next.next.next.next.next = head1.next.next.next; // 7->4

      // 0->9->8->2...
      head2 = new Node(0);
      head2.next = new Node(9);
      head2.next.next = new Node(8);
      head2.next.next.next = head1.next; // 8->2
      System.out.println(getIntersectNode(head1, head2).value);

      // 0->9->8->6->4->5->6..
      head2 = new Node(0);
      head2.next = new Node(9);
      head2.next.next = new Node(8);
      head2.next.next.next = head1.next.next.next.next.next; // 8->6
      System.out.println(getIntersectNode(head1, head2).value);
   }
}
```

### 不给头结点删除节点

题目：能不能不给单链表的头结点，只给想要删除的节点，就能做到在链表上把这个点删除掉？

解法：抖机灵的做法，把删除节点的下一个节点复制到当前节点，删除下一个节点。

弊端：无法删除链表最后一个节点；因为是复制节点，如果节点表示服务器，那就不可能这么操作。

# 二叉树

## 二叉树遍历

- 先序遍历：对于所有子树，先访问头结点-左节点-右节点
- 中序遍历：对于所有子树，先访问左结点-头节点-右节点
- 后序遍历：对于所有子树，先访问左结点-右节点-头节点

题目：二叉树节点结构 第一层1 第二层2 3 第三层 4 5 6 7。

**递归遍历**

递归序：1，2，4，4，4，5，5，5，2，1，3，6，6，6，3，7，7，7，3，1 相当于第一次到自己的时候输出一下，然后左子树走完后输出一下，右子树走完后输出一下。这是递归实现，所有的递归都可以用非递归替代。

先序遍历（头左右）：1，2，4，5，3，6，7 相当于递归序里第一次来到的时候打印，第二三次到的时候什么也不做

中序遍历（左头右）：4，2，5，1，6，3，7 相当于递归序里第二次来到的时候打印，第一三次到的时候什么也不做

后序遍历（左右头）：4，2，5，1，6，3，7 相当于递归序里第三次来到的时候打印，第一二次到的时候什么也不做

```
// 传统二叉树递归遍历
public static void pre(Node head) {
    if (head == null) {
        return;
    }
    System.out.println("先序遍历" + head.value);
    pre(head.left);
    System.out.println("中序遍历" + head.value);
    pre(head.right);
    System.out.println("后序遍历" + head.value);
}

// 递归序遍历
public static void f(Node head) {
    if (head == null) {
        return;
    }
    // 1-第1次到达
    f(head.left);
    // 2-第2次到达
    f(head.right);
    // 3-第2次到达
}
```

**非递归遍历**

```
import java.util.Stack;
public class Code03_UnRecursiveTraversalBT {
    public static class Node {
        public int value;
        public Node left;
        public Node right;
        public Node(int v) {
            value = v;
        }
    }

    // 先序遍历
    /*用栈实现：因为栈的特性是先进后出，右比左先压入，所以先打印左然后右
     * 1.栈压入头结点
     * 2.栈弹出节点，打印
     * 3.如果右节点存在，压入右节点
     * 4.如果左节点存在，压入左节点
     * 5.循环2,3,4
     * */
    public static void pre(Node head) {
        System.out.print("pre-order: ");
        if (head != null) {
            Stack<Node> stack = new Stack<Node>();
            stack.add(head);
            while (!stack.isEmpty()) {
                head = stack.pop();
                System.out.print(head.value + " ");
                if (head.right != null) {
                    stack.push(head.right);
                }
                if (head.left != null) {
                    stack.push(head.left);
                }
            }
        }
        System.out.println();
    }

    // 中序遍历
    /*用栈实现：因为栈的特性是先进后出，右比左先压入，所以先打印左然后右
     * 1.初始化当前cur为头结点
     * 2.从cur出发，依次压入所有左节点。直到为null.
     * 3.栈弹出节点，打印
     * 4.cur来到cur的右节点
     * 5.循环2,3,4
     * */
    public static void in(Node cur) {
        System.out.print("in-order: ");
        if (cur != null) {
            Stack<Node> stack = new Stack<Node>();
            while (!stack.isEmpty() || cur != null) {
                if (cur != null) {
                    // 第2步
                    stack.push(cur);
                    cur = cur.left;
                } else {
                    // 第3,4步
                    cur = stack.pop();
                    System.out.print(cur.value + " ");
                    cur = cur.right;
                }
            }
        }
        System.out.println();
    }

    // 后续遍历：解法1
    /*用栈实现：准备2个栈。因为栈的特性是先进后出，初步得到是头-右-左。直接利用栈s2逆序弹出就是左右头。
     * 1.栈压入头结点
     * 2.栈弹出节点，打印
     * 3.如果左节点存在，压入左节点
     * 4.如果右节点存在，压入右节点
     * 5.循环2,3,4
     * */
    public static void pos1(Node head) {
        System.out.print("pos-order: ");
        if (head != null) {
            Stack<Node> s1 = new Stack<Node>();
            Stack<Node> s2 = new Stack<Node>();
            s1.push(head);
            while (!s1.isEmpty()) {
                head = s1.pop(); // 头 右 左
                s2.push(head);
                if (head.left != null) {
                    s1.push(head.left);
                }
                if (head.right != null) {
                    s1.push(head.right);
                }
            }
            // 左 右 头
            while (!s2.isEmpty()) {
                System.out.print(s2.pop().value + " ");
            }
        }
        System.out.println();
    }

    // 后续遍历：解法2，很难想到这种思路
    /*思路：
     * 先看栈顶元素有无左孩子，有就入栈，这里完成左边界入栈。
     * 然后从栈顶peek，如果该节点没有左右孩子，则pop掉并打印，并且将该元素赋给变量h，再peek栈顶元素，这个节点因为是h的父元素，所以看有没有右孩子，如果有，将右孩子压入栈。
     * 将该节点右孩子处理完后，此节点被pop，以此类推。
     * */
    public static void pos2(Node h) {
        System.out.print("pos-order: ");
        if (h != null) {
            Stack<Node> stack = new Stack<Node>();
            stack.push(h);
            Node c = null;
            while (!stack.isEmpty()) {
                c = stack.peek();
                if (c.left != null && h != c.left && h != c.right) {
                    // 先压入所有左节点
                    stack.push(c.left);
                } else if (c.right != null && h != c.right) {
                    // 然后压入右节点
                    stack.push(c.right);
                } else {
                    // 先处理左树，然后处理右树，再处理头节点
                    System.out.print(stack.pop().value + " ");
                    h = c;
                }
            }
        }
        System.out.println();
    }

    public static void main(String[] args) {
        Node head = new Node(1);
        head.left = new Node(2);
        head.right = new Node(3);
        head.left.left = new Node(4);
        head.left.right = new Node(5);
        head.right.left = new Node(6);
        head.right.right = new Node(7);
        pre(head);
        System.out.println("========");
        in(head);
        System.out.println("========");
        pos1(head);
        System.out.println("========");
        pos2(head);
        System.out.println("========");
    }
}
