## 二叉树的最大宽度

题目：求每一层二叉树中最大宽度的层的宽度

- 解法1，利用map记录node来到的层数，方便遍历完一层后，才开始比较大小
- 解法2，不使用map,通过设置flag变量的方式，来发现某一层的结束

```
// 二叉树的最大宽度：解法1，利用map记录node来到的层数，方便遍历完一层后，才开始比较大小
public static int maxWidthUseMap(Node head) {
    if (head == null) {
        return 0;
    }
    Queue<Node> queue = new LinkedList<>();
    queue.add(head);
    // key 在 哪一层，value,
    HashMap<Node, Integer> levelMap = new HashMap<>();
    // 头结点在第1层，从第1层开始
    levelMap.put(head, 1);
    int curLevel = 1; // 当前你正在统计哪一层的宽度
    int curLevelNodes = 0; // 当前层curLevel层，宽度目前是多少
    // 最大宽度
    int max = 0;
    while (!queue.isEmpty()) {
        Node cur = queue.poll();
        int curNodeLevel = levelMap.get(cur);
        // 利用队列进行宽度优先遍历
        if (cur.left != null) {
            // 记录节点层数
            levelMap.put(cur.left, curNodeLevel + 1);
            queue.add(cur.left);
        }
        if (cur.right != null) {
            // 记录节点层数
            levelMap.put(cur.right, curNodeLevel + 1);
            queue.add(cur.right);
        }
        if (curNodeLevel == curLevel) {
            // 当前节点还在当前记录的层数上，宽度+1
            curLevelNodes++;
        } else {
            // 当前节点的层数不是当前记录的层数，那么一定是来到了下一层，可以小结比较了
            max = Math.max(max, curLevelNodes);
            // 记录的层数+1，已经来到新的下一层
            curLevel++;
            // 已经来到下新的下一层，宽度记录为1
            curLevelNodes = 1;
        }
    }
    // 最后比较全局最大宽度和最后一层的宽度
    max = Math.max(max, curLevelNodes);
    return max;
}

// 二叉树的最大宽度：解法2，不使用map,通过设置flag变量的方式，来发现某一层的结束
public static int maxWidthNoMap(Node head) {
    if (head == null) {
        return 0;
    }
    Queue<Node> queue = new LinkedList<>();
    queue.add(head);
    Node curEnd = head; // 当前层，最右节点是谁
    Node nextEnd = null; // 下一层，最右节点是谁
    int max = 0;
    int curLevelNodes = 0; // 当前层的节点数
    while (!queue.isEmpty()) {
        // 常规的宽度优先遍历
        Node cur = queue.poll();
        if (cur.left != null) {
            queue.add(cur.left);
            // 在当前层，就已经拿到下一层的最右一个节点
            nextEnd = cur.left;
        }
        if (cur.right != null) {
            queue.add(cur.right);
            nextEnd = cur.right;
        }
        // 当前层宽度++
        curLevelNodes++;
        // 当前节点来到当前层的最右节点时
        if (cur == curEnd) {
            max = Math.max(max, curLevelNodes);
            // 下一层马上要变成当前层了
            // 初始化下一层的宽度为0
            curLevelNodes = 0;
            // 把当前层的最右节点更新为下一层的最右节点，继续循环
            curEnd = nextEnd;
        }
    }
    return max;
}
```

## 二叉树的序列化和反序列化

内存里的一棵树如何变成字符串形式，又如何从字符串形式变成内存里的树。

思路：先序列化，将一棵树遍历（先序遍历），然后空就用#代替，存储成一个字符串。然后反序列化就是用一个队列将字符串拆成值并一一压入，再递归构建树。不是很难，**用什么逻辑序列化就是相同逻辑反序列化**。

- 按照先序遍历的逻辑，序列化和反序列化
- 按照宽度优先遍历逻辑，序列化和反序列化

```
/*
 * 二叉树可以通过先序、后序或者按层遍历的方式序列化和反序列化，
 * 以下代码全部实现了。
 * 但是，二叉树无法通过中序遍历的方式实现序列化和反序列化
 * 因为不同的两棵树，可能得到同样的中序序列，即便补了空位置也可能一样。
 * 比如如下两棵树
 *         __2
 *        /
 *       1
 *       和
 *       1__
 *          \
 *           2
 * 补足空位置的中序遍历结果都是{ null, 1, null, 2, null}
 *
 * */
  // 序列化：先序遍历，在遍历的时候，序列节点
    public static Queue<String> preSerial(Node head) {
        Queue<String> ans = new LinkedList<>();
        pres(head, ans);
        return ans;
    }
    public static void pres(Node head, Queue<String> ans) {
        if (head == null) {
            // 空需要补空，序列化空
            ans.add(null);
        } else {
            // 先序遍历，先加入到队列中，序列化节点
            ans.add(String.valueOf(head.value));
            pres(head.left, ans);
            pres(head.right, ans);
        }
    }

     // 反序列化：按照先序遍历的逻辑，反向操作
    public static Node buildByPreQueue(Queue<String> prelist) {
        if (prelist == null || prelist.size() == 0) {
            return null;
        }
        return preb(prelist);
    }
    public static Node preb(Queue<String> prelist) {
        // 和先序遍历的逻辑如出一辙
        String value = prelist.poll();
        if (value == null) {
            // 空返回空节点，反序列化节点
            return null;
        }
        // 反序列化的节点
        Node head = new Node(Integer.valueOf(value));
        // 反序列化的节点，补齐它的左子节点
        head.left = preb(prelist);
        // 反序列化的节点，补齐它的右子节点
        head.right = preb(prelist);
        return head;
    }

        // 序列化：按照层遍历即宽度优先遍历，在遍历的时候，序列节点
    public static Queue<String> levelSerial(Node head) {
        Queue<String> ans = new LinkedList<>();
        if (head == null) {
            // 空节点序列化补空
            ans.add(null);
        } else {
            // 在遍历的时候，序列节点
            ans.add(String.valueOf(head.value));
            Queue<Node> queue = new LinkedList<Node>();
            queue.add(head);
            while (!queue.isEmpty()) {
                head = queue.poll(); // head 父   子
                if (head.left != null) {
                    //  添加节点的时候，序列化
                    ans.add(String.valueOf(head.left.value));
                    queue.add(head.left);
                } else {
                    // 空节点也要序列化
                    ans.add(null);
                }
                if (head.right != null) {
                    ans.add(String.valueOf(head.right.value));
                    queue.add(head.right);
                } else {
                    ans.add(null);
                }
            }
        }
        return ans;
    }

    // 反序列化：按照宽度优先遍历，反向逻辑操作
    public static Node buildByLevelQueue(Queue<String> levelList) {
        // 边界条件
        if (levelList == null || levelList.size() == 0) {
            return null;
        }
        // 先反序列生成头结点
        Node head = generateNode(levelList.poll());
        // 建立需要while遍历的队列
        Queue<Node> queue = new LinkedList<Node>();
        if (head != null) {
            queue.add(head);
        }
        Node node = null;
        // 借助队列，遍历所有节点
        while (!queue.isEmpty()) {
            // 弹出反序列化的节点
            node = queue.poll();
            // 反序列化的节点的左子节点
            node.left = generateNode(levelList.poll());
            // 反序列化的节点的右子节点
            node.right = generateNode(levelList.poll());
            if (node.left != null) {
                // 不为空的节点，要加入到循环队列，方便后面继续宽度优先遍历
                queue.add(node.left);
            }
            if (node.right != null) {
                queue.add(node.right);
            }
        }
        return head;
    }

    // 节点生成函数
    public static Node generateNode(String val) {
        if (val == null) {
            return null;
        }
        return new Node(Integer.valueOf(val));
    }
```

## 二叉树任意节点的后继节点

题目：给你二叉树中的某个节点，返回该节点的后继节点

后继节点定义：对一棵二叉树进行中序遍历，遍历后的顺序，当前节点的后一个节点为该节点的后继节点。前驱结点：也是相对于中序遍历而言的。一个节点的前一个节点。

**中序遍历：对于每个节点，都按照左头右访问。**

- 解法1：先中序遍历然后存入一个List,然后再遍历找到当前节点的下一个节点，但是时间复杂度是O(N)
- 解法2：要求时间复杂度为O(K)，其中K为两个节点的距离

```
public class Code06_SuccessorNode {
    public static class Node {
        public int value;
        public Node left;
        public Node right;
        public Node parent;

        public Node(int data) {
            this.value = data;
        }
    }

    public static Node getSuccessorNode(Node node) {
        // 解法2：返回后继节点，利用中序遍历中后继节点的特性
        if (node == null) {
            return node;
        }
        if (node.right != null) {
            // 如果该节点有右孩子，那么右子树的最左节点就是后继节点。
            return getLeftMost(node.right);
        } else {
            // 如果该节点无右孩子，那么它的后继节点一定是往上找父节点，直到节点是其父节点的左孩子，返回。因为左头
            Node parent = node.parent;
            // 父节点不能为null,null表示到根节点了。同时只要当前节点是其父节点的右孩子，循环继续。直到节点是其父节点的左孩子，跳出循环。
            while (parent != null && parent.right == node) { // 当前节点是其父亲节点右孩子
                // 更新当前节点
                node = parent;
                // 取出当前节点的父节点
                parent = node.parent;
            }
            // 返回那个节点是其父节点的左孩子的节点，就是后继节点
            return parent;
        }
    }

    // 返回该节点的最左节点
    public static Node getLeftMost(Node node) {
        if (node == null) {
            return node;
        }
        // 只要节点的左节点不为空，就循环找，直到该节点的左节点为空。返回该节点
        while (node.left != null) {
            node = node.left;
        }
        return node;
    }

    public static void main(String[] args) {
        Node head = new Node(6);
        head.parent = null;
        head.left = new Node(3);
        head.left.parent = head;
        head.left.left = new Node(1);
        head.left.left.parent = head.left;
        head.left.left.right = new Node(2);
        head.left.left.right.parent = head.left.left;
        head.left.right = new Node(4);
        head.left.right.parent = head.left;
        head.left.right.right = new Node(5);
        head.left.right.right.parent = head.left.right;
        head.right = new Node(9);
        head.right.parent = head;
        head.right.left = new Node(8);
        head.right.left.parent = head.right;
        head.right.left.left = new Node(7);
        head.right.left.left.parent = head.right.left;
        head.right.right = new Node(10);
        head.right.right.parent = head.right;

        Node test = head.left.left;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head.left.left.right;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head.left;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head.left.right;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head.left.right.right;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head.right.left.left;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head.right.left;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head.right;
        System.out.println(test.value + " next: " + getSuccessorNode(test).value);
        test = head.right.right; // 10's next is null
        System.out.println(test.value + " next: " + getSuccessorNode(test));
    }
}
```

## 折纸问题

请把一段纸条竖着放在桌子上，然后从纸条的下边向上方对折1次，压出折痕后 展开。
此时折痕是凹下去的，即折痕突起的方向指向纸条的背面。
如果从纸条的下边向上方连续对折2次，压出折痕后展开，此时有三条折痕，从 上到下依次是下折痕、下折痕和上折痕。
给定一个输入参数N，代表纸条都从下边向上方连续对折N次。
请从上到下打印所有折痕的方向。
例如:N=1时，打印: down N=2时，打印: down down up
思路：试验一下会发现，每次折完之后，会在每个上一次出现的痕迹处上面出现一个凹痕下面出现一个凸痕，其实可以理解为树，这个数根节点是凹痕，然后所有左子树的根节点都是凹痕，所有右子树的根节点都是凸痕。然后通过中序遍历递归去实现打印。

```
public class Code07_PaperFolding {
    public static void printAllFolds(int N) {
        process(1, N, true);
        System.out.println();
    }

    // 当前你来了一个节点，脑海中想象的！
    // 这个节点在第i层，一共有N层，N固定不变的
    // 这个节点如果是凹的话，down = T
    // 这个节点如果是凸的话，down = F
    // 函数的功能：中序打印以你想象的节点为头的整棵树！
    public static void process(int i, int N, boolean down) {
        if (i > N) {
            return;
        }
        process(i + 1, N, true);
        // 这里打印，本质就是用递归模拟中序遍历
        System.out.print(down ? "凹 " : "凸 ");
        process(i + 1, N, false);
    }

    public static void main(String[] args) {
        int N = 4;
        printAllFolds(N);
    }
}
```

## 二叉树递归套路

本质利用递归遍历二叉树的便利性。

1. 假设以X节点为头，假设可以向X左子树和X右子树获取任何信息
2. 在上一步的假设下，套路以X为头结点的树，得到答案的可能性。(最重要)
3. 列出所有可能性后，确定到底需要向左树和右树获取什么样的信息
4. 把左树信息和右树信息整合，就是任何一棵子树需要返回的信息S
5. 递归函数都返回S,每棵子树都这么要求
6. 写代码，在代码中考虑如何把左树的信息和右树信息整合出整棵树的信息

### **套路实践-判断平衡二叉树**

题目：给定一棵二叉树的头结点head,返回这棵树是否为平衡二叉树ALV.

ALV平衡二叉树定义：必须是二叉搜索树；每个节点的左子树和右子树的高度差至多为1

```
public static boolean isBalanced2(Node head) {
    // 返回根节点的平衡性
    return process(head).isBalanced;
}

public static class Info {
    // 先组织定义任意节点的平衡性信息数据结构
    // 该节点下，是否是平衡二叉树ALV
    public boolean isBalanced;
    // 该节点下，树的高度
    public int height;

    public Info(boolean i, int h) {
        isBalanced = i;
        height = h;
    }
}

public static Info process(Node x) {
    // 返回任意节点的平衡性信息数据结构
    // 叶子节点，一定是平衡二叉树ALV,且高度为0
    if (x == null) {
        return new Info(true, 0);
    }
    // 获取左子树的平衡信息---套路步骤1
    Info leftInfo = process(x.left);
    // 获取右子树的平衡信息---套路步骤1
    Info rightInfo = process(x.right);
    // 当前节点的树的高度信息，就是取左右子树最大高度+1自己
    int height = Math.max(leftInfo.height, rightInfo.height) + 1;
    boolean isBalanced = true;
    // ---套路步骤2
    if (!leftInfo.isBalanced) {
        // 左子树不平衡，不是平衡树
        isBalanced = false;
    }
    // ---套路步骤2
    if (!rightInfo.isBalanced) {
        // 右子树不平衡，不是平衡树
        isBalanced = false;
    }
    // ---套路步骤2
    if (Math.abs(leftInfo.height - rightInfo.height) > 1) {
        // 左右子树的高度差大于1，也不是平衡树
        isBalanced = false;
    }
    return new Info(isBalanced, height);
}
```

### 套路实践-判断满二叉树

- 解法1：收集整棵树的高度h，和节点数n。满二叉树满足 : 2 ^ h - 1 == n

```
 // 解法1：收集整棵树的高度h，和节点数n。满二叉树满足 : 2 ^ h - 1 == n
 public static boolean isFull1(Node head) {
  if (head == null) {
   return true;
  }
  Info1 all = process1(head);
    // 满二叉树：节点数=(2^height) - 1
  return (1 << all.height) - 1 == all.nodes;
 }

 public static class Info1 {
    // 二叉树高度
  public int height;
    // 二叉树节点个数
  public int nodes;

  public Info1(int h, int n) {
   height = h;
   nodes = n;
  }
 }

 public static Info1 process1(Node head) {
  if (head == null) {
   return new Info1(0, 0);
  }
  Info1 leftInfo = process1(head.left);
  Info1 rightInfo = process1(head.right);
    // 高度，取左右子树中最高的那个+1自己
  int height = Math.max(leftInfo.height, rightInfo.height) + 1;
    // 节点个数，同理
  int nodes = leftInfo.nodes + rightInfo.nodes + 1;
  return new Info1(height, nodes);
 }
