### 套路实践-判断完全二叉树

完全二叉树：上面的层是满的，即使不满，那么一定是从左到右逐渐变满。

- 解法1：利用宽度优先遍历，排除两种情况后，一定是满二叉树。
- 解法2：二叉树递归套路，完全二叉树有4种情况。

```
import java.util.LinkedList;
// 测试链接 : https://leetcode.com/problems/check-completeness-of-a-binary-tree/
public class Code01_IsCBT {
   // 不要提交这个类
   public static class TreeNode {
      public int val;
      public TreeNode left;
      public TreeNode right;
      public TreeNode(int v) {
         val = v;
      }
   }

  //解法1：利用宽度优先遍历，排除两种情况后，一定是满二叉树。
   public static boolean isCompleteTree1(TreeNode head) {
      /*
      * 情况a：无左孩子，有右孩子
      * 情况b：遇到过节点的左右孩子不全的节点，且节点不是叶子节点。
      * */
      /* 具体分析：
      * 对一个节点而言有四种可能：
         1. 当前节点有两个孩子
         2.当前节点有左孩子 没有右孩子
         3，当前节点 没有左孩子  有 右孩子
         4，当前节点 没有孩子
         我们层次遍历每一个节点，若碰到3的情况 一定不是完全二叉树 ，直接返回，
         当我们 第一次碰到：  2 或者 4 的情况的时候， 这意味着我们之后遍历的节点都必须是叶子，否则不是完全二叉树。
         若程序能执行到结束， 返回 true；
      * */
      if (head == null) {
         return true;
      }
      LinkedList<TreeNode> queue = new LinkedList<>();
      // 是否遇到过左右两个孩子不双全的节点
      boolean leaf = false;
      TreeNode l = null;
      TreeNode r = null;
      queue.add(head);
      // 基于队列的宽度优先遍历
      while (!queue.isEmpty()) {
         head = queue.poll();
         l = head.left;
         r = head.right;
         if (
         // 情况a||情况b
               (l == null && r != null)||(leaf && !(l == null || r == null))

         ) {
            return false;
         }
         if (l != null) {
            queue.add(l);
         }
         if (r != null) {
            queue.add(r);
         }
         // 遇到了叶子节点，左右都没孩子，不双全，标记true
         if (l == null || r == null) {
            leaf = true;
         }
      }
      return true;
   }

   public static boolean isCompleteTree2(TreeNode head) {
      return process(head).isCBT;
   }

   public static class Info {
      // 节点的子树为满二叉树
      public boolean isFull;
      // 节点的子树为完全二叉树
      public boolean isCBT;
      // 节点的子树高度
      public int height;
      public Info(boolean full, boolean cbt, int h) {
         isFull = full;
         isCBT = cbt;
         height = h;
      }
   }

   // 解法2：二叉树递归套路，完全二叉树有4种情况。
   public static Info process(TreeNode x) {
      /*假设树有3层，
          1         1       1          1
         2    3     2  3    2   3     2   3
       4  5  6 7   4       4  5     4  5 6
      * 情况1：最后一层都满了，一定要求：左树是满树&右树是满树&左树高度=右树高度
      * 情况2：最后一层只有1个节点，一定要求：左树是完全树&右树是满树&左树高度=右树高度+1
      * 情况3：最后一层只有2个节点，一定要求：左树是满树&右树是满树&左树高度=右树高度+1
      * 情况4：最后一层只有3个节点，一定要求：左树是满树&右树是完全树&左树高度=右树高度
      * */
      if (x == null) {
         return new Info(true, true, 0);
      }
      Info leftInfo = process(x.left);
      Info rightInfo = process(x.right);
      int height = Math.max(leftInfo.height, rightInfo.height) + 1;
      boolean isFull = leftInfo.isFull && rightInfo.isFull && leftInfo.height == rightInfo.height;
      boolean isCBT = false;
      if (leftInfo.isFull && rightInfo.isFull && leftInfo.height == rightInfo.height) {
         // 情况1
         isCBT = true;
      } else if (leftInfo.isCBT && rightInfo.isFull && leftInfo.height == rightInfo.height + 1) {
         // 情况2
         isCBT = true;
      } else if (leftInfo.isFull && rightInfo.isFull && leftInfo.height == rightInfo.height + 1) {
         // 情况3
         isCBT = true;
      } else if (leftInfo.isFull && rightInfo.isCBT && leftInfo.height == rightInfo.height) {
         // 情况4
         isCBT = true;
      }
      return new Info(isFull, isCBT, height);
   }

   // for test
   public static TreeNode generateRandomBST(int maxLevel, int maxValue) {
      return generate(1, maxLevel, maxValue);
   }

   // for test
   public static TreeNode generate(int level, int maxLevel, int maxValue) {
      if (level > maxLevel || Math.random() < 0.5) {
         return null;
      }
      TreeNode head = new TreeNode((int) (Math.random() * maxValue));
      head.left = generate(level + 1, maxLevel, maxValue);
      head.right = generate(level + 1, maxLevel, maxValue);
      return head;
   }

   public static void main(String[] args) {
      int maxLevel = 5;
      int maxValue = 100;
      int testTimes = 1000000;
      for (int i = 0; i < testTimes; i++) {
         TreeNode head = generateRandomBST(maxLevel, maxValue);
         if (isCompleteTree1(head) != isCompleteTree2(head)) {
            System.out.println("Oops!");
         }
      }
      System.out.println("finish!");
   }
}
```

