        // 1.先逆序所有的右节点
        Node tail = reverseEdge(head);
        Node cur = tail;
        while (cur != null) {
            // 2.打印所有右节点
            System.out.print(cur.value + " ");
            cur = cur.right;
        }
        // 3.再还原回来，因为是在原树上处理，没有额外空间
        reverseEdge(tail);
    }
    public static Node reverseEdge(Node from) {
        // 逆序所有的右节点，和链表逆序原理一致
        Node pre = null;
        Node next = null;
        while (from != null) {
            next = from.right;
            from.right = pre;
            pre = from;
            from = next;
        }
        return pre;
    }
