    public static void g1(char[] str, int index, List<String> ans) {
        // 索引已经来到最后一个字符，找到了字符串，加入到list
        if (index == str.length) {
            ans.add(String.valueOf(str));
        } else {
            // 尝试将索引值index及其后续的字符交换到index上，找到字符串
            for (int i = index; i < str.length; i++) {
                // 交换
                swap(str, index, i);
                // 递归下一个索引值
                g1(str, index + 1, ans);
                // 每次交换完，再恢复到原始现场，方便下次递归使用原始变量
                swap(str, index, i);
            }
        }
    }
