 public static class Node<V> {
     // value的类型为泛型，单链表结构
  public V value;
  public Node<V> next;

  public Node(V v) {
   value = v;
   next = null;
  }
 }

 public static class MyQueue<V> {
     // 基于链表结构的队列，先进先出。只需要记录头尾指针，内部的跳转使用单链表关联起来。
     // 头指针
  private Node<V> head;
  // 尾指针
  private Node<V> tail;
  private int size;

  public MyQueue() {
   head = null;
   tail = null;
   size = 0;
  }

  public boolean isEmpty() {
   return size == 0;
  }

  public int size() {
   return size;
  }

  public void offer(V value) {
      // 队列添加数据
      // cur是单链表结构
   Node<V> cur = new Node<V>(value);
   if (tail == null) {
       // 全空，则头尾指针指向当前节点
    head = cur;
    tail = cur;
   } else {
       // 尾巴的节点先指向当前节点
    tail.next = cur;
    // 然后尾巴指针指向当前节点
    tail = cur;
   }
   size++;
  }

  // C/C++的同学需要做节点析构的工作
  public V poll() {
      // 队列弹出数据
   V ans = null;
   if (head != null) {
       // 直接取出头指针节点
    ans = head.value;
    // 头指针下移一个
    head = head.next;
    size--;
   }
   if (head == null) {
    tail = null;
   }
   return ans;
  }

  // C/C++的同学需要做节点析构的工作
  public V peek() {
      // 查询队列的头结点
   V ans = null;
   if (head != null) {
    ans = head.value;
   }
   return ans;
  }
 }
}
