 public static class Node<V> {
     // 双链表，不复杂，就是两个指针，一个往前指，一个往后指
  public V value;
  public Node<V> last;
  public Node<V> next;

  public Node(V v) {
   value = v;
   last = null;
   next = null;
  }
 }

 public static class MyDeque<V> {
     // 基于双链表实现的双端队列，即头部可添加删除元素，尾部也可添加删除元素
     // 依然是头指针和尾指针
  private Node<V> head;
  private Node<V> tail;
  private int size;

  public MyDeque() {

   head = null;
   tail = null;
   size = 0;
  }

  public boolean isEmpty() {
   return size == 0;
  }

  public int size() {
   return size;
  }

  public void pushHead(V value) {
      // 头部添加元素
   Node<V> cur = new Node<>(value);
   if (head == null) {
       // 先判空，头尾指针都指向当前节点
    head = cur;
    tail = cur;
   } else {
       // 当前节点的下一个指针指向老头指针
    cur.next = head;
    // 老头指针指向当前节点
    head.last = cur;
    // 头指针变成当前节点
    head = cur;
   }
   // 队列长度+1
   size++;
  }

  public void pushTail(V value) {
      // 尾部添加元素
   Node<V> cur = new Node<>(value);
   if (head == null) {
    head = cur;
    tail = cur;
   } else {
    tail.next = cur;
    cur.last = tail;
    tail = cur;
   }
   size++;
  }

  public V pollHead() {
      // 头部弹出元素
   V ans = null;
   if (head == null) {
    return ans;
   }
   size--;
   ans = head.value;
   if (head == tail) {
    head = null;
    tail = null;
   } else {
    head = head.next;
    head.last = null;
   }
   return ans;
  }

  public V pollTail() {
      // 尾部弹出元素
   V ans = null;
   if (head == null) {
    return ans;
   }
   size--;
   ans = tail.value;
   if (head == tail) {
    head = null;
    tail = null;
   } else {
    tail = tail.last;
    tail.next = null;
   }
   return ans;
  }

  public V peekHead() {
      // 头部查询元素
   V ans = null;
   if (head != null) {
    ans = head.value;
   }
   return ans;
  }

  public V peekTail() {
      // 尾部查询元素
   V ans = null;
   if (tail != null) {
    ans = tail.value;
   }
   return ans;
  }

 }
}
