## 单链表的k个节点的组内逆序调整

```
import java.util.*;
import java.lang.*;
import java.io.*;
class Codechef
{
 public static void main (String[] args) throws java.lang.Exception
 {
     // 该算法难度为hard,一定要画图，否则玩个6啊
     // 测试链接：https://leetcode.com/problems/reverse-nodes-in-k-group/
     //单链表的k个节点的组内逆序调整，不足k个的不需要逆序。
     // 1-2-3-4-5-6-7-8逆序后3-2-1-6-5-4-7-8
     ListNode node = new ListNode(1);
     node.next = new ListNode(2);
     node.next.next = new ListNode(3);
     node.next.next.next = new ListNode(4);
     node.next.next.next.next = new ListNode(5);
     node.next.next.next.next.next = new ListNode(6);
     node.next.next.next.next.next.next = new ListNode(7);
     node.next.next.next.next.next.next.next = new ListNode(8);
     node = reverseKGroup(node,3);
     for(int i =0;i<8;i++){
         System.out.print(node.val+"->");
         node = node.next;
     }
 }

 // 不要提交这个类
 public static class ListNode<V> {
  public V val;
  public ListNode<V> next;
  public ListNode(V value){
      val = value;
      next = null;
  }
 }

 public static ListNode reverseKGroup(ListNode head, int k) {
  ListNode start = head;
  ListNode end = getKGroupEnd(start, k);
  if (end == null) {
      // 不足一组k个的情况，不用反转，直接返回头结点
   return head;
  }
  // 第一组凑齐了！
  head = end;
  // 第一组直接反转
  reverse(start, end);
  // 当前组的最后一个节点是逆序后的原头节点
  ListNode lastEnd = start;
  while (lastEnd.next != null) {
      // 继续组内的头结点到尾节点的反转操作
   start = lastEnd.next;
   end = getKGroupEnd(start, k);
   if (end == null) {
       // 当前组不需要反转，直接返回外层的头结点
    return head;
   }
   reverse(start, end);
   // 逆序后，上一组的尾节点指向当前组的逆序后的头节点
   lastEnd.next = end;
   // 将上一组的尾节点变为当前组的逆序后的尾节点
   lastEnd = start;
  }
  return head;
 }

 public static ListNode getKGroupEnd(ListNode start, int k) {
     // 已知节点，获取同组第k个节点
  while (--k != 0 && start != null) {
  // k=0表示k个节点，同时节点不能为空
  // 根据链表特性，依次获取下去
   start = start.next;
  }
  // 返回从开始节点算起的第k个节点
  return start;
 }

 public static void reverse(ListNode start, ListNode end) {
     // 将一组内的k个节点，全部反转
     // 先将尾指针指向最后一个的下一个
  end = end.next;
  ListNode pre = null;
  // 将头节点给起当前节点
  ListNode cur = start;
  ListNode next = null;
  // 循环逆序当前这一组
  while (cur != end) {
      // 链表反转的经典常规操作
   next = cur.next;
   cur.next = pre;
   pre = cur;
   cur = next;
  }
  // 原来的头结点指向下一组的第一个节点
  start.next = end;
 }
}
```

## 两个链表相加

```
import java.util.*;
import java.lang.*;
import java.io.*;
class Codechef
{
 // 测试链接：https://leetcode.com/problems/add-two-numbers/
 public static void main (String[] args) throws java.lang.Exception
 {
     // 两个链表相加，计算进位信息
     // 1-2-3-4和9-4-8-9-9相加得0-7-1-4-0-1
     ListNode node = new ListNode(1);
     node.next = new ListNode(2);
     node.next.next = new ListNode(3);
     node.next.next.next = new ListNode(4);
     ListNode node1 = new ListNode(9);
     node1.next = new ListNode(4);
     node1.next.next = new ListNode(8);
     node1.next.next.next = new ListNode(9);
     node1.next.next.next.next = new ListNode(9);
     node = addTwoNumbers(node,node1);
     while(node != null){
         System.out.print(node.val+"->");
         node = node.next;
     }
 }

 // 不要提交这个类
 public static class ListNode {
  public int val;
  public ListNode next;

  public ListNode(int val) {
   this.val = val;
  }

  public ListNode(int val, ListNode next) {
   this.val = val;
   this.next = next;
  }
 }

 public static ListNode addTwoNumbers(ListNode head1, ListNode head2) {
     // 两个链表相加，从左到右依次为低位到高位，有进位要计算进位
  int len1 = listLength(head1);
  int len2 = listLength(head2);
  // 获取两个链表中的哪一个长，哪一个短一些
  ListNode l = len1 >= len2 ? head1 : head2;
  ListNode s = l == head1 ? head2 : head1;
  /*
   计算分三步走：
   第一步：l节点有值，s节点有值，则直接计算ls包括进位符，该进位进位
   第二步：l有值，s无值，则直接计算l包括进位符，该进位进位
   第三部：l无值，s无值，则看进位符是否有，高位新增一个节点，保存进位值
  */
  ListNode curL = l;
  ListNode curS = s;
  ListNode last = curL;
  // 表示当前进位符
  int carry = 0;
  int curNum = 0;
  while (curS != null) {
      // 第一步，l+s+carry进位符
   curNum = curL.val + curS.val + carry;
   // 取余，最终结果复制到长链表中
   curL.val = (curNum % 10);
   // 更新进位符
   carry = curNum / 10;
   // 时刻跟随最新的节点
   last = curL;
   // 长短链表，依次往下指
   curL = curL.next;
   curS = curS.next;
  }
  while (curL != null) {
       // 第二步
   curNum = curL.val + carry;
   curL.val = (curNum % 10);
   carry = curNum / 10;
   last = curL;
   curL = curL.next;
  }
  if (carry != 0) {
       // 第三步，如果最后一个还有进位，则追加一个链表节点到最后
   last.next = new ListNode(1);
  }
  return l;
 }

 // 求链表长度
 public static int listLength(ListNode head) {
  int len = 0;
  while (head != null) {
   len++;
   head = head.next;
  }
  return len;
 }
}
```

## 链表套路

套路：

- 对于笔试，不用关注空间复杂度，一切为了时间复杂度。比如：hash表，数组等
- 对于面试，时间复杂度依然第一，还要找到空间最省的方法。比如：快慢指针

### 快慢指针

定义：一般情况下，快指针的移动步长为慢指针的两倍。利用快慢指针，我们把一个链表看成一个跑道，假设**a**的速度是**b**的两倍，那么当**a**跑完全程后，**b**刚好跑一半，以 此来 达到找到中间节点的目的。

题目：

1. 输入链表头结点，奇数长度返回中点，偶数长度返回上中点
2. 输入链表头结点，奇数长度返回中点，偶数长度返回下中点
3. 输入链表头结点，奇数长度返回中点前一个，偶数长度返回上中点前一个
4. 输入链表头结点，奇数长度返回中点前一个，偶数长度返回下中点前一个

- 解法1：暴力求解，把节点加入到数组中，二分取值---用于笔试
- 解法2：快慢指针，---用于面试，如果笔试中能写出也可以

```
import java.util.ArrayList;
public class Code01_LinkedListMid {
   public static class Node {
      public int value;
      public Node next;
      public Node(int v) {
         value = v;
      }
   }
   // 判断链表中是否存在环
   public boolean hasCycle(Node head) {
      if (head == null)
         return false;
      //快慢两个指针，初始时都指向链表的头结点
      Node slow = head;
      Node fast = head;
      while (fast != null && fast.next != null) {
         //慢指针每次走一步
         slow = slow.next;
         //快指针每次走两步
         fast = fast.next.next;
         //如果相遇，说明有环，直接返回true
         if (slow == fast)
            return true;
      }
      //否则就是没环
      return false;
   }

   // 题目1：解法2：快慢指针，---用于面试，如果笔试中能写出也可以
   public static Node midOrUpMidNode(Node head) {
      // 链表没有节点，有1个节点，2个节点
      if (head == null || head.next == null || head.next.next == null) {
         return head;
      }
      // 链表有3个点或以上
      // 根据题意，确定快慢指针的起始位置，起始值位置不用记忆，直接按照结果尝试奇偶即可
      Node slow = head.next;
      Node fast = head.next.next;
      // 快慢指针的走法都是每次慢指针走一步，快指针走两步
      while (fast.next != null && fast.next.next != null) {
         slow = slow.next;
         fast = fast.next.next;
      }
      return slow;
   }
   // 题目2
   public static Node midOrDownMidNode(Node head) {
      if (head == null || head.next == null) {
         return head;
      }
      Node slow = head.next;
      Node fast = head.next;
      while (fast.next != null && fast.next.next != null) {
         slow = slow.next;
         fast = fast.next.next;
      }
      return slow;
   }
   // 题目3
   public static Node midOrUpMidPreNode(Node head) {
      if (head == null || head.next == null || head.next.next == null) {
         return null;
      }
      Node slow = head;
      Node fast = head.next.next;
      while (fast.next != null && fast.next.next != null) {
         slow = slow.next;
         fast = fast.next.next;
      }
      return slow;
   }
   // 题目4
   public static Node midOrDownMidPreNode(Node head) {
      if (head == null || head.next == null) {
         return null;
      }
      if (head.next.next == null) {
         return head;
      }
      Node slow = head;
      Node fast = head.next;
      while (fast.next != null && fast.next.next != null) {
         slow = slow.next;
         fast = fast.next.next;
      }
      return slow;
   }
   // 题目1：解法1：暴力求解，把节点加入到数组中，二分取值---用于笔试
   public static Node right1(Node head) {
      if (head == null) {
         return null;
      }
      Node cur = head;
      ArrayList<Node> arr = new ArrayList<>();
      while (cur != null) {
         arr.add(cur);
         cur = cur.next;
      }
      return arr.get((arr.size() - 1) / 2);
   }

   public static Node right2(Node head) {
      if (head == null) {
         return null;
      }
      Node cur = head;
      ArrayList<Node> arr = new ArrayList<>();
      while (cur != null) {
         arr.add(cur);
         cur = cur.next;
      }
      return arr.get(arr.size() / 2);
   }

   public static Node right3(Node head) {
      if (head == null || head.next == null || head.next.next == null) {
         return null;
      }
      Node cur = head;
      ArrayList<Node> arr = new ArrayList<>();
      while (cur != null) {
         arr.add(cur);
         cur = cur.next;
      }
      return arr.get((arr.size() - 3) / 2);
   }

   public static Node right4(Node head) {
      if (head == null || head.next == null) {
         return null;
      }
      Node cur = head;
      ArrayList<Node> arr = new ArrayList<>();
      while (cur != null) {
         arr.add(cur);
         cur = cur.next;
      }
      return arr.get((arr.size() - 2) / 2);
   }

   public static void main(String[] args) {
      Node test = null;
      test = new Node(0);
      test.next = new Node(1);
      test.next.next = new Node(2);
      test.next.next.next = new Node(3);
      test.next.next.next.next = new Node(4);
      test.next.next.next.next.next = new Node(5);
      test.next.next.next.next.next.next = new Node(6);
