      System.out.println(ans1 != null ? ans1.value : "无");
      System.out.println(ans2 != null ? ans2.value : "无");

      ans1 = midOrDownMidNode(test);
      ans2 = right2(test);
      System.out.println(ans1 != null ? ans1.value : "无");
      System.out.println(ans2 != null ? ans2.value : "无");

      ans1 = midOrUpMidPreNode(test);
      ans2 = right3(test);
      System.out.println(ans1 != null ? ans1.value : "无");
      System.out.println(ans2 != null ? ans2.value : "无");

