### 链表是否回文

题目：给定一个单链表头结点head,请判断该链表是否为回文结构

- 栈方法特别简单---笔试用
- 改原链表的方法就需要注意边界---面试用

解法：

- 解法1：把链表所有节点放进栈中，然后逐一出栈(相当于逆序)和链表逐一比对
- 解法2：利用快慢指针，找到中点或上中点。中点以后的节点全部入栈，然后逐一出栈(相当于逆序)和链表逐一比对，直到栈空为止。可以想象成纸对折逐一比对。
- 解法3：不使用额外空间，利用快慢指针，找到中点或上中点。中点以后的节点全部逆序指向，定义左右两个指针，逐一比较。

```
import java.util.Stack;
public class Code02_IsPalindromeList {
   public static class Node {
      public int value;
      public Node next;
      public Node(int data) {
         this.value = data;
      }
   }

   // 解法1：把链表所有节点放进栈中，然后逐一出栈(相当于逆序)和链表逐一比对
   public static boolean isPalindrome1(Node head) {
      Stack<Node> stack = new Stack<Node>();
      Node cur = head;
      while (cur != null) {
         stack.push(cur);
         cur = cur.next;
      }
      while (head != null) {
         if (head.value != stack.pop().value) {
            return false;
         }
         head = head.next;
      }
      return true;
   }

   // 解法2：利用快慢指针，找到中点或上中点。中点以后的节点全部入栈，然后逐一出栈(相当于逆序)和链表逐一比对，直到栈空为止。可以想象成纸对折逐一比对。
   public static boolean isPalindrome2(Node head) {
      if (head == null || head.next == null) {
         return true;
      }
      Node right = head.next;
      Node cur = head;
      while (cur.next != null && cur.next.next != null) {
         right = right.next;
         cur = cur.next.next;
      }
      Stack<Node> stack = new Stack<Node>();
      while (right != null) {
         stack.push(right);
         right = right.next;
      }
      while (!stack.isEmpty()) {
         if (head.value != stack.pop().value) {
            return false;
         }
         head = head.next;
      }
      return true;
   }

   // 解法3：不使用额外空间，利用快慢指针，找到中点或上中点。中点以后的节点全部逆序指向，定义左右两个指针，逐一比较。
   public static boolean isPalindrome3(Node head) {
      /*
      * 1->2->3->->3->2->1
      *    null
      *     ^
      *      |
      * 1->2-3<<-3<-2<-1
      * n2             n1 n3
      * */
      if (head == null || head.next == null) {
         return true;
      }
      Node n1 = head;// 慢指针
      Node n2 = head;// 快指针
      while (n2.next != null && n2.next.next != null) { // find mid node
         n1 = n1.next; // n1 -> mid
         n2 = n2.next.next; // n2 -> end
      }
      // n1 中点
      // 把n1以后的节点全部逆序指向
      n2 = n1.next; // n2 -> right part first node
      n1.next = null; // mid.next -> null
      Node n3 = null;
      while (n2 != null) { // right part convert
         n3 = n2.next; // n3 -> save next node
         n2.next = n1; // next of right node convert
         n1 = n2; // n1 move
         n2 = n3; // n2 move
      }
      // 临时记录下右节点
      n3 = n1; // n3 -> save last node
      n2 = head;// n2 -> left first node
      boolean res = true;
      // 比较左右节点是否相等
      while (n1 != null && n2 != null) { // check palindrome
         if (n1.value != n2.value) {
            res = false;
            break;
         }
         n1 = n1.next; // left to mid
         n2 = n2.next; // right to mid
      }
      // 将n3-...>n1指向逆序还原回来
      n1 = n3.next;
      n3.next = null;
      while (n1 != null) { // recover list
         n2 = n1.next;
         n1.next = n3;
         n3 = n1;
         n1 = n2;
      }
      return res;
   }

   public static void printLinkedList(Node node) {
      System.out.print("Linked List: ");
      while (node != null) {
         System.out.print(node.value + " ");
         node = node.next;
      }
      System.out.println();
   }

   public static void main(String[] args) {
      Node head = null;
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      head.next = new Node(2);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      head.next = new Node(1);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      head.next = new Node(2);
      head.next.next = new Node(3);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      head.next = new Node(2);
      head.next.next = new Node(1);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      head.next = new Node(2);
      head.next.next = new Node(3);
      head.next.next.next = new Node(1);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      head.next = new Node(2);
      head.next.next = new Node(2);
      head.next.next.next = new Node(1);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");

      head = new Node(1);
      head.next = new Node(2);
      head.next.next = new Node(3);
      head.next.next.next = new Node(2);
      head.next.next.next.next = new Node(1);
      printLinkedList(head);
      System.out.print(isPalindrome1(head) + " | ");
      System.out.print(isPalindrome2(head) + " | ");
      System.out.println(isPalindrome3(head) + " | ");
      printLinkedList(head);
      System.out.println("=========================");
   }
}
```

### 链表的复制

题目：一种特殊的单链表结构，其中有个Node rand随机属性。rand可能指向任意节点，也可能指向null.请设计一个函数完成这个链表的复制，返回复制的链表的头结点。

- 解法1：把所有节点放入hashmap,从头结点开始遍历，依次copy出新链表
- 解法2：在每个节点后面插入前一个节点的copy节点，然后设置radom，再分离新老节点

```
import java.util.HashMap;
// 测试链接 : https://leetcode.com/problems/copy-list-with-random-pointer/
public class Code04_CopyListWithRandom {
 public static class Node {
  int val;
  Node next;
  Node random;

  public Node(int val) {
   this.val = val;
   this.next = null;
   this.random = null;
  }
 }

 // 解法1：把所有节点放入hashmap,从头结点开始遍历，依次copy出新链表
 public static Node copyRandomList1(Node head) {
  // key 老节点
  // value 新节点
  HashMap<Node, Node> map = new HashMap<Node, Node>();
  Node cur = head;
  // 所有节点放入hashmap
  while (cur != null) {
   map.put(cur, new Node(cur.val));
   cur = cur.next;
  }
  cur = head;
  // 从头结点开始遍历，依次copy
  while (cur != null) {
   // cur 老节点
   // map.get(cur) 新节点
   // 新.next ->  cur.next克隆节点找到
   map.get(cur).next = map.get(cur.next);
   map.get(cur).random = map.get(cur.random);
   cur = cur.next;
  }
  return map.get(head);
 }

 // 解法2：在每个节点后面插入前一个节点的copy节点，然后设置radom，再分离新老节点
 public static Node copyRandomList2(Node head) {
  if (head == null) {
   return null;
  }
  Node cur = head;
  Node next = null;
  // 1 -> 2 -> 3 -> null
  // 1 -> 1' -> 2 -> 2' -> 3 -> 3'
  // 每个节点后面插入前一个节点的copy节点
  while (cur != null) {
   next = cur.next;
   cur.next = new Node(cur.val);
   cur.next.next = next;
   cur = next;
  }
  cur = head;
  Node copy = null;
  // 1 1' 2 2' 3 3'， 其中1‘是1的复制节点
  // 依次设置 1' 2' 3' 的random指针
  while (cur != null) {
   next = cur.next.next;
   copy = cur.next;
   // 注意cur.random的节点 一定是对应cur.random.next。因为下一个节点是当前节点的复制。
   copy.random = cur.random != null ? cur.random.next : null;
   cur = next;
  }
  Node res = head.next;
  cur = head;
  // 老 新 混在一起，next方向上，random正确
  // next方向上，把新老链表分离，一定动手实际画图，想是想不清楚的
  while (cur != null) {
   next = cur.next.next;
   copy = cur.next;
   cur.next = next;
   copy.next = next != null ? next.next : null;
   cur = next;
  }
  return res;
 }
}
```

### 两链表是否相交

题目：给定两个可能有环也可能无环的单链表，头节点head1和head2。请实 现一个函数，如果两个链表相交，请返回相交的 第一个节点。如果不相交，返 回null。要求时间复杂度O(N),空间复杂度O(1)

思路：这是一个超大题目。涉及知识点：

- 必考知识点：找到链表第一个入环节点，如果无环，返回null
- 必考知识点：如果两个链表都无环，返回第一个相交节点，如果不想交，返回null
- 必考知识点：两个有环链表，返回第一个相交节点，如果不想交返回null

解法：

- 解法：先求链表的入环节点，然后按照无环和有环分情况讨论

```java
public class Code01_FindFirstIntersectNode {
   public static class Node {
      public int value;
      public Node next;
      public Node(int data) {
         this.value = data;
      }
   }

   public static Node getIntersectNode(Node head1, Node head2) {
      // 解法：先求链表的入环节点，然后按照无环和有环分情况讨论
      if (head1 == null || head2 == null) {
         return null;
      }
      // 找到链表第一个入环节点，如果无环，返回null
      Node loop1 = getLoopNode(head1);
      Node loop2 = getLoopNode(head2);
      // 如果两个链表都是无环链表
      if (loop1 == null && loop2 == null) {
         return noLoop(head1, head2);
      }
      // 如果两个链表都是有环链表
      if (loop1 != null && loop2 != null) {
         return bothLoop(head1, loop1, head2, loop2);
      }
      // 一链表有环，一链表无环，一定不会相交。画画图就知道了
      return null;
   }

   // 必考知识点：找到链表第一个入环节点，如果无环，返回null
   public static Node getLoopNode(Node head) {
      /*
      * 解法1：用额外空间，遍历链表，每到一个节点就判断是否在Set里，如果突然发现在了。说明是第一个入环节点。
      * 解法2：快慢指针，慢指针一定不会走够两圈以上，在环内相遇时，将快指针放到开头，慢指针原地不动。然后两个开始一次走一步，最后会在入环节点相遇。本文采用解法2.
      * */
      if (head == null || head.next == null || head.next.next == null) {
         return null;
      }
      // n1 慢指针  n2 快指针，让n1,n2都先走一次，方便下面的while判断
      Node slow = head.next; // n1 -> slow
      Node fast = head.next.next; // n2 -> fast
      while (slow != fast) {
         if (fast.next == null || fast.next.next == null) {
            return null;
         }
         fast = fast.next.next;
         slow = slow.next;
      }
      // 到这里，说明slow fast  相遇了
      // 抖机灵做法：快指针回到头结点，然后快慢指针再次相遇，就是入环节点
      fast = head; // n2 -> walk again from head
      while (slow != fast) {
         slow = slow.next;
         fast = fast.next;
      }
      return slow;
   }

   // 必考知识点：如果两个链表都无环，返回第一个相交节点，如果不想交，返回null
   public static Node noLoop(Node head1, Node head2) {
      /*
      * 先统计head1到end1并且记住长度假设是100，然后统计head2和end2并且记住长度假设是80。如果end1！=end2则没有相交部分。
      * 如果一样，则head1先走20步，然后一起走直到找到相同内存的节点，即相交节点。可以通过n记录链表一和二的长度之差，节约一个变量。
      * */
      if (head1 == null || head2 == null) {
         return null;
      }
      Node cur1 = head1;
      Node cur2 = head2;
      int n = 0;
      while (cur1.next != null) {
         n++;
         cur1 = cur1.next;
      }
      while (cur2.next != null) {
         n--;
         cur2 = cur2.next;
      }
      // 因为是无环链表，如果最后的节点都不相同，结果一定是不相交，后续不用执行
      if (cur1 != cur2) {
         return null;
      }
      // n 表示链表1长度减去链表2长度的值
      cur1 = n > 0 ? head1 : head2; // 谁长，谁的头变成cur1
      cur2 = cur1 == head1 ? head2 : head1; // 谁短，谁的头变成cur2
      n = Math.abs(n);
      // 长链表减去多余的部分，然后一起往下走
      while (n != 0) {
         n--;
         cur1 = cur1.next;
      }
      // 如果相遇，则是相交点
      while (cur1 != cur2) {
         cur1 = cur1.next;
         cur2 = cur2.next;
      }
      return cur1;
   }

   // 必考知识点：两个有环链表，返回第一个相交节点，如果不想交返回null
   public static Node bothLoop(Node head1, Node loop1, Node head2, Node loop2) {
      /*
      * 情况1：如果有入环节点相同
      * 情况2:如果有入环点不同，可能有两个入环点
      * 情况3：如果有入环点不同，可能不相交
      * */
      Node cur1 = null;
      Node cur2 = null;
      // 情况1：和前面的无环链表判断类似，只不过节点找到入环节点就可以，也没有入环节点的判断
      if (loop1 == loop2) {
         cur1 = head1;
         cur2 = head2;
         int n = 0;
         while (cur1 != loop1) {
            n++;
            cur1 = cur1.next;
         }
         while (cur2 != loop2) {
            n--;
            cur2 = cur2.next;
         }
         cur1 = n > 0 ? head1 : head2;
         cur2 = cur1 == head1 ? head2 : head1;
         n = Math.abs(n);
         while (n != 0) {
            n--;
            cur1 = cur1.next;
         }
         while (cur1 != cur2) {
            cur1 = cur1.next;
            cur2 = cur2.next;
         }
         return cur1;
      } else {
         // 情况2
         cur1 = loop1.next;
         // 链表1从自己的入环点开始遍历一圈，找下是否有节点和链表2的入环点相同，相同即返回节点
         while (cur1 != loop1) {
            if (cur1 == loop2) {
               return loop1;// 或返回loop2都行，因为有2个入环点，随便一个都可以
            }
            cur1 = cur1.next;
         }
         //情况3
         return null;
      }
   }

   public static void main(String[] args) {
      // 1->2->3->4->5->6->7->null
      Node head1 = new Node(1);
      head1.next = new Node(2);
      head1.next.next = new Node(3);
      head1.next.next.next = new Node(4);
      head1.next.next.next.next = new Node(5);
      head1.next.next.next.next.next = new Node(6);
      head1.next.next.next.next.next.next = new Node(7);

      // 0->9->8->6->7->null
      Node head2 = new Node(0);
      head2.next = new Node(9);
      head2.next.next = new Node(8);
      head2.next.next.next = head1.next.next.next.next.next; // 8->6
      System.out.println(getIntersectNode(head1, head2).value);

      // 1->2->3->4->5->6->7->4...
      head1 = new Node(1);
      head1.next = new Node(2);
      head1.next.next = new Node(3);
      head1.next.next.next = new Node(4);
      head1.next.next.next.next = new Node(5);
      head1.next.next.next.next.next = new Node(6);
      head1.next.next.next.next.next.next = new Node(7);
      head1.next.next.next.next.next.next = head1.next.next.next; // 7->4

      // 0->9->8->2...
      head2 = new Node(0);
      head2.next = new Node(9);
      head2.next.next = new Node(8);
      head2.next.next.next = head1.next; // 8->2
      System.out.println(getIntersectNode(head1, head2).value);

      // 0->9->8->6->4->5->6..
      head2 = new Node(0);
      head2.next = new Node(9);
      head2.next.next = new Node(8);
      head2.next.next.next = head1.next.next.next.next.next; // 8->6
      System.out.println(getIntersectNode(head1, head2).value);
   }
}
