            for (int i = index; i < str.length; i++) {
                // 交换
                swap(str, index, i);
                // 递归下一个索引值
                g1(str, index + 1, ans);
                // 每次交换完，再恢复到原始现场，方便下次递归使用原始变量
                swap(str, index, i);
            }
        }
    }
