# 线段树

定义：是一棵二叉树。它的特点是：每个结点表示的是一个线段，或者说是一个区间。

```java
public class Code01_SegmentTree {
    // 线段树的实现
    public static class SegmentTree {
        // arr[]为原序列的信息从0开始，但在arr里是从1开始的，注意从下标1开始是为了方便使用位运算。
        // MAXN是拷贝数组的长度
        // sum[]模拟线段树维护区间和
        // lazy[]为累加和标记即懒加和标记
        // change[]为更新的值
        // update[]为更新标记即懒更新标记
        private int[] arr;
        private int MAXN;
        private int[] sum;
        private int[] lazy;
        private int[] change;
        private boolean[] update;

        // 构造函数,初始化所有数组空间
        public SegmentTree(int[] origin) {
            // 创建原数组origin对应的拷贝数组arr，从下标1开始，方便后续的位运算
            MAXN = origin.length + 1;
            arr = new int[MAXN]; // arr[0] 不用 从1开始使用
            for (int i = 1; i < MAXN; i++) {
                arr[i] = origin[i - 1];
            }
            // 为了把所有数都刚好让左右等范围cover住，申请长度MAXN*4即左移2位
            sum = new int[MAXN << 2]; // 用来支持脑补概念中，某一个范围的累加和信息
            lazy = new int[MAXN << 2]; // 用来支持脑补概念中，某一个范围沒有往下傳遞的纍加任務
            change = new int[MAXN << 2]; // 用来支持脑补概念中，某一个范围有没有更新操作的任务
            update = new boolean[MAXN << 2]; // 用来支持脑补概念中，某一个范围更新任务，更新成了什么
        }

        // 当前节点收集左右子节点的和信息。懒加和，懒更新后，都需要执行这个操作
        private void pushUp(int rt) {
            /*
             * rt是当前节点索引
             * rt对应的左子节点是rt*2即rt << 1
             * rt对应的右子节点是rt*2+1即rt << 1|1
             * */
            sum[rt] = sum[rt << 1] + sum[rt << 1 | 1];
        }

        // 下发懒更新和懒加和。懒加和，懒更新，都需要把自己的任务下发给左右子节点。分发策略:从父范围，分发给左右边界
        private void pushDown(int rt, int ln, int rn) {
            /*
             * ln表示左子树元素结点个数，rn表示右子树结点个数
             * */
            // 如果当前节点懒更新标记为true,则下发懒更新
            if (update[rt]) {
                /*
                 * 下发给左右节点懒更新时，
                 * 左右节点的懒更新标记为true
                 * 左右节点的懒更新值为父节点值
                 * 左右节点的懒加和清空，置为0
                 * 左右节点的区间和，直接计算为长度*懒更新值
                 * 当前自己节点的懒更新标记为false，清空，表示后续不用再下发
                 * */
                update[rt << 1] = true;
                update[rt << 1 | 1] = true;
                change[rt << 1] = change[rt];
                change[rt << 1 | 1] = change[rt];
                lazy[rt << 1] = 0;
                lazy[rt << 1 | 1] = 0;
                sum[rt << 1] = change[rt] * ln;
                sum[rt << 1 | 1] = change[rt] * rn;
                update[rt] = false;
            }
            // 如果当前节点懒加和标记不为0,则下发懒加和
            if (lazy[rt] != 0) {
                /*
                 * 下发给左右节点懒加和时，
                 * 左右节点的懒加和=之前的值+当前父节点的值
                 * 左右节点的区间和=当前懒加和*长度
                 * 当前自己节点的懒加和标记为0，清空，表示后续不用再下发
                 * */
                lazy[rt << 1] += lazy[rt];
                lazy[rt << 1 | 1] += lazy[rt];
                sum[rt << 1] += lazy[rt] * ln;
                sum[rt << 1 | 1] += lazy[rt] * rn;
                lazy[rt] = 0;
            }
        }

        // 初始化线段树：构建线段树的初值，sum数组填充。
        public void build(int l, int r, int rt) {
            /*
             * 在arr[l~r]范围上，去build构建sum数组信息。
             * rt是sum数组的下标索引
             * */
            if (l == r) {
                sum[rt] = arr[l];
                return;
            }
            int mid = (l + r) >> 1;
            build(l, mid, rt << 1);
            build(mid + 1, r, rt << 1 | 1);
            pushUp(rt);
        }

        // 在L到R索引范围上，每个元素都加上C
        public void add(int L, int R, int C, int l, int r, int rt) {
            /*
             *L~R, C 表示任务的3个变量
             * l,r是线段树的某个节点的左右区间，rt是某个节点的索引。这三个值可以认为是固定值。
             * */
            // 任务如果把此时的范围全包了！那么这个节点区间直接命中
            if (L <= l && r <= R) {
                // 区间和=之前值+c*区间长度
                sum[rt] += C * (r - l + 1);
                // 懒加载和=之前值+当前值C
                lazy[rt] += C;
                return;
            }
            // 如果任务没有把你全包！
            // 取二分中点，l  r  mid = (l+r)/2
            int mid = (l + r) >> 1;
            // 先下发懒更新和懒加和
            pushDown(rt, mid - l + 1, r - mid);
            // 如果任务的左边界越过区间的中点，去左边了，则去左子节点继续递归。rt << 1等于rt*2
            if (L <= mid) {
                add(L, R, C, l, mid, rt << 1);
            }
            // 如果任务的右边界越过区间的中点，去右边了，则去右子节点继续递归.rt << 1|1等于rt*2+1
            if (R > mid) {
                add(L, R, C, mid + 1, r, rt << 1 | 1);
            }
            // 等前面的子节点信息填好了后，再当前节点收集左右子节点的和信息
            pushUp(rt);
        }

        // 在L到R索引范围上，每个元素都更新为C
        public void update(int L, int R, int C, int l, int r, int rt) {
            /*
             *L~R, C 表示任务的3个变量
             * l,r是线段树的某个节点的左右区间，rt是某个节点的索引。这三个值可以认为是固定值。
             * */
            // 任务如果把此时的范围全包了！那么这个节点区间直接命中
            if (L <= l && r <= R) {
                /*
                 * 当前节点的懒更新标记为true
                 * 当前节点的懒更新值为C
                 * 当前节点的区间和=C*区间长度
                 * 当前节点的懒加和清空，为0
                 * */
                update[rt] = true;
                change[rt] = C;
                sum[rt] = C * (r - l + 1);
                lazy[rt] = 0;
                return;
            }
            // 当前任务躲不掉，无法懒更新，要往下发
            int mid = (l + r) >> 1;
            // 先下发懒更新和懒加和
            pushDown(rt, mid - l + 1, r - mid);
            // 如果任务的左边界越过区间的中点，去左边了，则去左子节点继续递归。rt << 1等于rt*2
            if (L <= mid) {
                update(L, R, C, l, mid, rt << 1);
            }
            // 如果任务的右边界越过区间的中点，去右边了，则去右子节点继续递归.rt << 1|1等于rt*2+1
            if (R > mid) {
                update(L, R, C, mid + 1, r, rt << 1 | 1);
            }
            // 等前面的子节点信息填好了后，再当前节点收集左右子节点的和信息
            pushUp(rt);
        }

        // 查询L~R上的累加和是多少
        public long query(int L, int R, int l, int r, int rt) {
            /*
             *L~R 表示任务的2个变量
             * l,r是线段树的某个节点的左右区间，rt是某个节点的索引。这三个值可以认为是固定值。
             * */
            // 任务区间包括了节点的区间值，命中
            if (L <= l && r <= R) {
                return sum[rt];
            }
            int mid = (l + r) >> 1;
            // 先下发懒更新和懒加和
            pushDown(rt, mid - l + 1, r - mid);
            long ans = 0;
            // 如果任务的左边界越过区间的中点，去左边了。去左节点收集和
            if (L <= mid) {
                ans += query(L, R, l, mid, rt << 1);
            }
            // 如果任务的右边界越过区间的中点，去右边了。去右节点收集和
            if (R > mid) {
                ans += query(L, R, mid + 1, r, rt << 1 | 1);
            }
            // 最后返回
            return ans;
        }

    }

    public static class Right {
        // 对数器：最暴力的直接求和
        public int[] arr;

        public Right(int[] origin) {
            arr = new int[origin.length + 1];
            for (int i = 0; i < origin.length; i++) {
                arr[i + 1] = origin[i];
            }
        }

        public void update(int L, int R, int C) {
            for (int i = L; i <= R; i++) {
                arr[i] = C;
            }
        }

        public void add(int L, int R, int C) {
            for (int i = L; i <= R; i++) {
                arr[i] += C;
            }
        }

        public long query(int L, int R) {
            long ans = 0;
            for (int i = L; i <= R; i++) {
                ans += arr[i];
            }
            return ans;
        }

    }

    public static int[] genarateRandomArray(int len, int max) {
        int size = (int) (Math.random() * len) + 1;
        int[] origin = new int[size];
        for (int i = 0; i < size; i++) {
            origin[i] = (int) (Math.random() * max) - (int) (Math.random() * max);
        }
        return origin;
    }

    public static boolean test() {
        int len = 100;
        int max = 1000;
        int testTimes = 5000;
        int addOrUpdateTimes = 1000;
        int queryTimes = 500;
        for (int i = 0; i < testTimes; i++) {
            int[] origin = genarateRandomArray(len, max);
            SegmentTree seg = new SegmentTree(origin);
            /*
             * S,N是线段树的某个节点的左右区间，root是某个节点的索引。这三个值可以认为是固定值。
             * */
            int S = 1;
            int N = origin.length;
            int root = 1;
            // 初始化线段树
            seg.build(S, N, root);
            // 对数器的数组
            Right rig = new Right(origin);
            for (int j = 0; j < addOrUpdateTimes; j++) {
                int num1 = (int) (Math.random() * N) + 1;
                int num2 = (int) (Math.random() * N) + 1;
                int L = Math.min(num1, num2);
                int R = Math.max(num1, num2);
                int C = (int) (Math.random() * max) - (int) (Math.random() * max);
                if (Math.random() < 0.5) {
                    // 等概率小于0.5的添加值
                    seg.add(L, R, C, S, N, root);
                    rig.add(L, R, C);
                } else {
                    // 等概率大于等于0.5的更新值
                    seg.update(L, R, C, S, N, root);
                    rig.update(L, R, C);
                }
            }
            // 测试500次，和对数器逐一比对，死都测出来
            for (int k = 0; k < queryTimes; k++) {
                int num1 = (int) (Math.random() * N) + 1;
                int num2 = (int) (Math.random() * N) + 1;
                int L = Math.min(num1, num2);
                int R = Math.max(num1, num2);
                long ans1 = seg.query(L, R, S, N, root);
                long ans2 = rig.query(L, R);
                if (ans1 != ans2) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] origin = {2, 1, 1, 2, 3, 4, 5};
        SegmentTree seg = new SegmentTree(origin);
        int S = 1; // 整个区间的开始位置，规定从1开始，不从0开始 -> 固定
        int N = origin.length; // 整个区间的结束位置，规定能到N，不是N-1 -> 固定
        int root = 1; // 整棵树的头节点位置，规定是1，不是0 -> 固定
        int L = 2; // 操作区间的开始位置 -> 可变
        int R = 5; // 操作区间的结束位置 -> 可变
        int C = 4; // 要加的数字或者要更新的数字 -> 可变
        // 区间生成，必须在[S,N]整个范围上build
        seg.build(S, N, root);
        // 区间修改，可以改变L、R和C的值，其他值不可改变
        seg.add(L, R, C, S, N, root);
        // 区间更新，可以改变L、R和C的值，其他值不可改变
        seg.update(L, R, C, S, N, root);
        // 区间查询，可以改变L和R的值，其他值不可改变
        long sum = seg.query(L, R, S, N, root);
        System.out.println(sum);

        System.out.println("对数器测试开始...");
        System.out.println("测试结果 : " + (test() ? "通过" : "未通过"));
    }
}
